  // Get Urdu translation for a commodity
  static String getUrduName(String englishName) {
    return _urduTranslations[englishName] ?? englishName;
  }

  // Search commodities by English name
  static List<String> searchCommodities(String query) {
    final results = <String>[];
    final lowerQuery = query.toLowerCase();
    
    final allCommodities = getAllCommodities();
    
    // First, find exact prefix matches (highest priority)
    final prefixMatches = <String>[];
    for (final commodity in allCommodities) {
      if (commodity.toLowerCase().startsWith(lowerQuery)) {
        prefixMatches.add(commodity);
      }
    }
    
    // Then find substring matches (lower priority)
    final substringMatches = <String>[];
    for (final commodity in allCommodities) {
      if (!prefixMatches.contains(commodity) &&
          commodity.toLowerCase().contains(lowerQuery)) {
        substringMatches.add(commodity);
      }
    }
    
    results.addAll(prefixMatches);
    results.addAll(substringMatches);
    
    return results.take(10).toList(); // Limit to 10 results
  }

  // Get all commodity names
  static List<String> getAllCommodities() {
    return _urduTranslations.keys.toList()
      ..remove('Commodity Types')
      ..sort();
  }

  // Check if commodity exists
  static bool commodityExists(String name) {
    return _urduTranslations.containsKey(name);
  }
